 return comments.some(q=>q.user?.id===OWNER_ID && q.created_at===q.updated_at && q.body.startsWith('<!-- factory:question:v2 ') && q.body.includes('"question":"'+match[1]+'"') && Date.parse(c.created_at)>Date.parse(q.created_at));
